/**
 * FNV-1a 32-bit hash → float in [0, 1).
 * Deterministic across browsers; stable for long-running experiments.
 */
export function hashToUnitInterval(input: string): number {
  let hash = 0x811c9dc5;
  for (let i = 0; i < input.length; i++) {
    hash ^= input.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193);
  }
  // >>> 0 forces unsigned 32-bit
  return (hash >>> 0) / 0x100000000;
}

export interface WeightedVariant {
  key: string;
  weight: number;
}

/** Map a unit interval to a weighted variant key. */
export function pickWeightedVariant(
  unit: number,
  variants: WeightedVariant[],
): string | null {
  const total = variants.reduce((sum, v) => sum + Math.max(0, v.weight), 0);
  if (total <= 0 || variants.length === 0) return null;

  let cursor = unit * total;
  for (const v of variants) {
    const w = Math.max(0, v.weight);
    if (cursor < w) return v.key;
    cursor -= w;
  }
  return variants[variants.length - 1]?.key ?? null;
}

export function bucketVariant(
  stableId: string,
  experimentKey: string,
  variants: WeightedVariant[],
): string | null {
  const unit = hashToUnitInterval(`${stableId}:${experimentKey}`);
  return pickWeightedVariant(unit, variants);
}

/** Returns true if unit falls within the first `percent` of [0, 100). */
export function inRollout(stableId: string, key: string, percent: number): boolean {
  if (percent >= 100) return true;
  if (percent <= 0) return false;
  const unit = hashToUnitInterval(`${stableId}:rollout:${key}`);
  return unit * 100 < percent;
}
